<?php
$uid = (int)$u['id'];
handle('off_issue', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Offline::issue($uid, (string)$_POST['to'], (string)$_POST['amount']); $_SESSION['off_token'] = $r; return 'One-time offline token prepared. Nothing has been charged yet.'; });
echo page_head('Offline QR', 'Prepare a one-time, expiring payment token for a merchant who may be offline. It settles only when the merchant syncs.');
echo '<div class="alert info">SIMULATION: tokens are authenticated-encrypted (AES-256-GCM), single-use and expire. They are <strong>not</strong> settled when created or scanned. At sync the server re-checks your balance, the expiry and replays, so an offline token can never bypass double-spend protection.</div>';
if (!empty($_SESSION['off_token'])) { $o = $_SESSION['off_token']; unset($_SESSION['off_token']); echo card('Your offline token', '<div class="qr" data-qr="' . e($o['token']) . '"></div><p>Payee: <strong>' . e($o['payee']) . '</strong> &middot; expires ' . e(fdate($o['expires'])) . '</p><textarea id="otok" rows="3" readonly class="mono">' . e($o['token']) . '</textarea><p style="margin-top:8px"><button type="button" class="btn secondary sm" data-copy="otok">Copy token</button></p><p class="hint">Show the QR code or give this text to the merchant. Status: ISSUED, not settled.</p>'); }
$ts = rows('SELECT o.*, u.name FROM offline_tokens o JOIN users u ON u.id=o.payee_user_id WHERE o.user_id=? ORDER BY o.id DESC LIMIT 15', [$uid]); $rows = [];
foreach ($ts as $t) { $st = $t['status'] === 'issued' && strtotime($t['expires_at']) < time() ? 'expired' : $t['status']; $rows[] = [e(fdate($t['created_at'])), e($t['name']), mny($t['amount']), e(fdate($t['expires_at'])), badge($st), $t['txn_id'] ? ref_link((string)val('SELECT ref FROM transactions WHERE id=?', [$t['txn_id']])) : '-']; }
echo '<div class="grid g-main">' . card('Your offline tokens', tbl(['Created', 'Merchant', ['Amount', 'num'], 'Expires', 'Status', 'Txn'], $rows, 'No offline tokens yet.')) . card('Prepare a token', form_start('off_issue') . field('Merchant', 'to', 'text', 'merchant@auvryon.test', 'required placeholder="merchant email or phone"') . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . pin_field() . btn('Prepare offline token') . '</form><p class="hint">Valid for ' . floor((int)setting('offline_token_ttl_seconds') / 60) . ' minutes. Tokens outstanding plus the new amount cannot exceed your balance.</p>') . '</div>';
